import{c as t,Q as n,j as i,m as r}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Profil Bisnis & Akun","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/pengaturan.md","filePath":"panduan/pengaturan.md"}'),e={name:"panduan/pengaturan.md"};function o(g,a,s,d,l,u){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="profil-bisnis-akun" tabindex="-1">Profil Bisnis &amp; Akun <a class="header-anchor" href="#profil-bisnis-akun" aria-label="Permalink to &quot;Profil Bisnis &amp; Akun&quot;">​</a></h1><hr><h2 id="profil-bisnis" tabindex="-1">Profil Bisnis <a class="header-anchor" href="#profil-bisnis" aria-label="Permalink to &quot;Profil Bisnis&quot;">​</a></h2><p>Buka <strong>Pengaturan → Profil Bisnis</strong></p><p>Informasi ini digunakan di berbagai tempat: kop surat kontrak, invoice, halaman tanda tangan, dan footer email notifikasi.</p><table tabindex="0"><thead><tr><th>Field</th><th>Digunakan di</th></tr></thead><tbody><tr><td><strong>Nama Bisnis</strong></td><td>Kop surat, header invoice, email</td></tr><tr><td><strong>Alamat Bisnis</strong></td><td>Kop surat, invoice, footer email</td></tr><tr><td><strong>Nomor Telepon</strong></td><td>Kop surat, invoice, halaman verifikasi kontrak</td></tr><tr><td><strong>Email Bisnis</strong></td><td>Kop surat, invoice</td></tr><tr><td><strong>Logo</strong></td><td>Invoice, halaman tanda tangan kontrak</td></tr><tr><td><strong>Tanda Tangan Admin</strong></td><td>Tampil di halaman kontrak sebagai tanda tangan pihak operator</td></tr></tbody></table><h3 id="mengganti-logo" tabindex="-1">Mengganti Logo <a class="header-anchor" href="#mengganti-logo" aria-label="Permalink to &quot;Mengganti Logo&quot;">​</a></h3><ol><li>Di bagian <strong>Logo</strong>, klik <strong>Pilih File</strong> dan pilih gambar (PNG, JPG, SVG — maks 2 MB)</li><li>Preview akan tampil setelah file dipilih</li><li>Klik <strong>Simpan Profil</strong></li></ol><h3 id="mengganti-tanda-tangan-admin" tabindex="-1">Mengganti Tanda Tangan Admin <a class="header-anchor" href="#mengganti-tanda-tangan-admin" aria-label="Permalink to &quot;Mengganti Tanda Tangan Admin&quot;">​</a></h3><ol><li>Di area tanda tangan, gambar tanda tangan baru menggunakan mouse atau jari (di layar sentuh)</li><li>Klik <strong>Hapus</strong> jika ingin menggambar ulang</li><li>Klik <strong>Simpan Profil</strong></li></ol><hr><h2 id="sub-pengguna" tabindex="-1">Sub-Pengguna <a class="header-anchor" href="#sub-pengguna" aria-label="Permalink to &quot;Sub-Pengguna&quot;">​</a></h2><p>Sub-pengguna memungkinkan Anda memberikan akses terbatas ke staf atau teknisi tanpa membagikan kredensial akun utama.</p><p>Buka <strong>Pengaturan → Sub-Pengguna</strong></p><h3 id="tambah-sub-pengguna" tabindex="-1">Tambah Sub-Pengguna <a class="header-anchor" href="#tambah-sub-pengguna" aria-label="Permalink to &quot;Tambah Sub-Pengguna&quot;">​</a></h3><ol><li>Klik <strong>+ Tambah Sub-Pengguna</strong></li><li>Isi:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Email</strong></td><td>Alamat email untuk login</td></tr><tr><td><strong>Nama Tampilan</strong></td><td>Nama yang ditampilkan di dasbor</td></tr><tr><td><strong>Password</strong></td><td>Password login sub-pengguna</td></tr></tbody></table><ol start="3"><li>Atur <strong>izin akses</strong> per fitur:</li></ol><table tabindex="0"><thead><tr><th>Fitur</th><th>Izin yang Bisa Diberikan</th></tr></thead><tbody><tr><td>PPPoE Pelanggan</td><td>Lihat / Tambah &amp; Edit / Hapus</td></tr><tr><td>Tagihan</td><td>Lihat / Konfirmasi Pembayaran</td></tr><tr><td>Hotspot Voucher</td><td>Lihat / Generate / Hapus</td></tr><tr><td>Keuangan</td><td>Lihat</td></tr><tr><td>Pengaturan Router</td><td>Lihat / Edit</td></tr></tbody></table><ol start="4"><li>Klik <strong>Simpan</strong></li></ol><p>Sub-pengguna dapat login dengan email dan password yang ditetapkan. Mereka tidak bisa melihat atau mengubah pengaturan di luar izin yang diberikan.</p><h3 id="edit-hapus-sub-pengguna" tabindex="-1">Edit &amp; Hapus Sub-Pengguna <a class="header-anchor" href="#edit-hapus-sub-pengguna" aria-label="Permalink to &quot;Edit &amp; Hapus Sub-Pengguna&quot;">​</a></h3><p>Klik ikon <strong>pensil</strong> untuk mengubah izin atau data, atau ikon <strong>hapus</strong> untuk menonaktifkan akses.</p><hr><h2 id="langganan-eznom" tabindex="-1">Langganan eznom <a class="header-anchor" href="#langganan-eznom" aria-label="Permalink to &quot;Langganan eznom&quot;">​</a></h2><p>Buka <strong>Pengaturan → Langganan</strong> untuk melihat status langganan Anda ke platform eznom, termasuk:</p><ul><li>Paket yang aktif</li><li>Tanggal kedaluwarsa</li><li>Riwayat pembayaran langganan</li></ul>',27)])])}const p=t(e,[["render",o]]);export{m as __pageData,p as default};
